290	/// Load a config file as raw YAML Value (for merging).
291	///
292	/// Returns the raw serde_yaml::Value without deserializing into
293	/// BivvyConfig, which allows for deep merging before final parsing.
294	pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
295	    let content = fs::read_to_string(path).map_err(|e| {
296	        if e.kind() == std::io::ErrorKind::NotFound {
297	            BivvyError::ConfigNotFound {
298	                path: path.to_path_buf(),
299	            }
300	        } else {
301	            BivvyError::Io(e)
302	        }
303	    })?;
304	
305	    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
306	        path: path.to_path_buf(),
307	        message: e.to_string(),
308	    })
309	}
