19	}
20	
21	impl ConfigCommand {
22	    /// Create a new config command.
23	    pub fn new(project_root: &Path, args: ConfigArgs) -> Self {
24	        Self {
25	            project_root: project_root.to_path_buf(),
26	            args,
27	            config_override: None,
28	        }
29	    }
30	
31	    /// Set an override config path.
32	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
33	        self.config_override = config_override;
34	        self
35	    }
36	
37	    /// Get the project root path.
38	    pub fn project_root(&self) -> &Path {
39	        &self.project_root
40	    }
41	
42	    /// Get the command arguments.
43	    pub fn args(&self) -> &ConfigArgs {
44	        &self.args
45	    }
46	}
47	
48	impl Command for ConfigCommand {
49	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
50	        let paths = ConfigPaths::discover(&self.project_root);
51	
52	        // Load configuration: override path, merged (all sources), or project-only
53	        let config = if let Some(ref override_path) = self.config_override {
54	            load_config_file(override_path)?
55	        } else if self.args.merged {
56	            match load_merged_config(&self.project_root) {
57	                Ok(c) => c,
58	                Err(BivvyError::ConfigNotFound { .. }) => {
59	                    ui.error("No configuration found. Run 'bivvy init' first.");
60	                    return Ok(CommandResult::failure(2));
61	                }
62	                Err(e) => return Err(e),
63	            }
64	        } else {
65	            // Load only the project config (.bivvy/config.yml) without merging
66	            match &paths.project {
67	                Some(project_path) => load_config_file(project_path)?,
68	                None => {
69	                    ui.error("No configuration found. Run 'bivvy init' first.");
70	                    return Ok(CommandResult::failure(2));
71	                }
72	            }
73	        };
74	
75	        // Apply config default_output when no CLI flag was explicitly set
76	        if ui.output_mode() == OutputMode::Normal {
77	            ui.set_output_mode(config.settings.defaults.output.into());
78	        }
79	
80	        // Show config file path(s)
81	        if self.args.merged {
82	            let existing: Vec<_> = paths.all_existing();
83	            if !existing.is_empty() {
84	                for path in &existing {
85	                    ui.message(&format!("# {}", path.display()));
86	                }
87	                ui.message("");
88	            }
89	        } else if let Some(project_path) = &paths.project {
90	            ui.message(&format!("# {}", project_path.display()));
91	            ui.message("");
92	        }
93	
94	        // Output format
95	        if self.args.json {
96	            let json =
97	                serde_json::to_string_pretty(&config).map_err(|e| BivvyError::Other(e.into()))?;
98	            ui.message(&json);
99	        } else {
100	            // --yaml or default: output as YAML
101	            let yaml = serde_yaml::to_string(&config).map_err(|e| BivvyError::Other(e.into()))?;
102	            ui.message(&yaml);
103	        }
104	
105	        Ok(CommandResult::success())
106	    }
107	}
